const path=require("path"),fs=require("fs");let translations={},currentLang="en";function detectSystemLanguage(){return Intl.DateTimeFormat().resolvedOptions().locale.split("-")[0]}function loadTranslations(){currentLang=detectSystemLanguage();const t=path.join(__dirname,"locales",`${currentLang}.json`);if(fs.existsSync(t))translations=JSON.parse(fs.readFileSync(t,"utf-8"));else{const t=path.join(__dirname,"locales","en.json");translations=fs.existsSync(t)?JSON.parse(fs.readFileSync(t,"utf-8")):{}}}function t(t){return Object.prototype.hasOwnProperty.call(translations,t)?translations[t]:null}function tDom(n){n.querySelectorAll("[data-i18n]").forEach((n=>{const e=t(n.getAttribute("data-i18n"));e&&(n.textContent=e)}))}loadTranslations(),module.exports={t:t,tDom:tDom,currentLang:currentLang};